def fibonacci(n):
    """
    Returns the n-th Fibonacci number iteratively.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for i in range(2, n + 1):
            a, b = b, a + b
        return b

